import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import axios from "axios";

function Signup({ onSignup }) {
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);

  const navigate = useNavigate();

  function handleSubmit(e) {
    e.preventDefault();

    axios
      .post("http://localhost:8080/signup", {
        firstName,
        lastName,
        email,
        password,
      })
      .then((res) => {
        console.log("✅ Signup response:", res.data);
        alert(res.data.message);

        // Check if signup was successful (user object exists in response)
        if (res.data.user) {
          console.log("📝 User object found, storing and redirecting...");
          localStorage.setItem("user", JSON.stringify(res.data.user));
          onSignup(res.data.user);
          // Navigate to dashboard after a short delay to ensure state updates
          setTimeout(() => {
            navigate("/dashboard");
          }, 100);
        } else {
          console.warn("⚠️ No user object in response:", res.data);
        }
      })
      .catch((err) => {
        console.error("❌ Signup error:", err);
        if (err.response?.data?.message) {
          alert(`Error: ${err.response.data.message}`);
        } else {
          alert("Signup failed. Please try again.");
        }
      });
  }

  return (
    <section className="page auth-page fade-in">
      <h1 className="slide-up">Create your SciHub account</h1>

      <form className="auth-form slide-up" onSubmit={handleSubmit}>
        <label>
          First Name
          <input
            type="text"
            required
            value={firstName}
            onChange={(e) => setFirstName(e.target.value)}
          />
        </label>

        <label>
          Last Name
          <input
            type="text"
            required
            value={lastName}
            onChange={(e) => setLastName(e.target.value)}
          />
        </label>

        <label>
          Email
          <input
            type="email"
            required
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </label>

        <label>
          Password
          <div style={{ position: "relative" }}>
            <input
              type={showPassword ? "text" : "password"}
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ paddingRight: "2.5rem" }}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              style={{
                position: "absolute",
                right: "0.5rem",
                top: "50%",
                transform: "translateY(-50%)",
                background: "none",
                border: "none",
                color: "var(--text-muted)",
                cursor: "pointer",
              }}
            >
              {showPassword ? "Hide" : "Show"}
            </button>
          </div>
        </label>

        <button type="submit" className="primary-btn">
          Sign up
        </button>
      </form>

      <p className="slide-up">
        Already have an account?{" "}
        <Link className="link-btn" to="/login">
          Log in
        </Link>
      </p>
    </section>
  );
}

export default Signup;
